class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)
        pre = [0] * (n + 1)
        cs = [0] * (n + 1)
        for i in range(n):
            pre[i + 1] = pre[i] + nums[i]
            cs[i + 1] = cs[i] + cost[i]
        INF = float('inf')
        dp = [[INF] * (n + 1) for _ in range(n + 1)]
        dp[0][0] = 0
        for j in range(1, n + 1):
            for i in range(j, n + 1):
                for l in range(j - 1, i):
                    if dp[j - 1][l] < INF:
                        v = dp[j - 1][l] + (pre[i] + k * j) * (cs[i] - cs[l])
                        if v < dp[j][i]:
                            dp[j][i] = v
        return dp[n][n]

