    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)
        pre = [0] * (n + 1)
        cs = [0] * (n + 1)
        for i in range(n):
            pre[i + 1] = pre[i] + nums[i]
            cs[i + 1] = cs[i] + cost[i]
        INF = float('inf')
        dp = [INF] * (n + 1)
        dp[0] = 0
        for j in range(1, n + 1):
            nd = [INF] * (n + 1)
            ms, bs, ptr = [], [], 0
            for i in range(j, n + 1):
                pv = dp[i - 1]
                if pv < INF:
                    m, b = -cs[i - 1], pv
                    while len(ms) >= 2 and (b - bs[-2]) * (ms[-1] - ms[-2]) <= (bs[-1] - bs[-2]) * (m - ms[-2]):
                        ms.pop(); bs.pop()
                    ms.append(m); bs.append(b)
                if ms:
                    x = pre[i] + k * j
                    if ptr >= len(ms):
                        ptr = len(ms) - 1
                    while ptr + 1 < len(ms) and ms[ptr + 1] * x + bs[ptr + 1] <= ms[ptr] * x + bs[ptr]:
                        ptr += 1
                    nd[i] = ms[ptr] * x + bs[ptr] + x * cs[i]
            dp = nd
        return dp[n]

