        vector<long long> pre(n + 1, 0), cs(n + 1, 0);
        for (int i = 0; i < n; i++) { pre[i + 1] = pre[i] + nums[i]; cs[i + 1] = cs[i] + cost[i]; }
        const long long INF = LLONG_MAX / 4;
        vector<long long> dp(n + 1, INF), nd(n + 1);
        dp[0] = 0;
        for (int j = 1; j <= n; j++) {
            fill(nd.begin(), nd.end(), INF);
            vector<long long> ms, bs;
            int ptr = 0;
            for (int i = j; i <= n; i++) {
                long long pv = dp[i - 1];
                if (pv < INF) {
                    long long m = -cs[i - 1], b = pv;
                    while (ms.size() >= 2 && (__int128)(b - bs[bs.size() - 2]) * (ms[ms.size() - 1] - ms[ms.size() - 2]) <= (__int128)(bs[bs.size() - 1] - bs[bs.size() - 2]) * (m - ms[ms.size() - 2])) {
                        ms.pop_back(); bs.pop_back();
                    }
                    ms.push_back(m); bs.push_back(b);
                }
                if (!ms.empty()) {
                    long long x = pre[i] + (long long)k * j;
                    if (ptr >= (int)ms.size()) ptr = ms.size() - 1;
                    while (ptr + 1 < (int)ms.size() && ms[ptr + 1] * x + bs[ptr + 1] <= ms[ptr] * x + bs[ptr]) ptr++;
                    nd[i] = ms[ptr] * x + bs[ptr] + x * cs[i];
                }
            }
            swap(dp, nd);
        }
        return dp[n];
    }
