class Solution {
    public long minimumCost(int[] nums, int[] cost, int k) {
        int n = nums.length;
        long[] pre = new long[n + 1], cs = new long[n + 1];
        for (int i = 0; i < n; i++) { pre[i + 1] = pre[i] + nums[i]; cs[i + 1] = cs[i] + cost[i]; }
        final long INF = Long.MAX_VALUE / 4;
        long[] dp = new long[n + 1], nd = new long[n + 1];
        java.util.Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int j = 1; j <= n; j++) {
            java.util.Arrays.fill(nd, INF);
            java.util.ArrayList<Long> ms = new java.util.ArrayList<>(), bs = new java.util.ArrayList<>();
            int ptr = 0;
            for (int i = j; i <= n; i++) {
                long pv = dp[i - 1];
                if (pv < INF) {
                    long m = -cs[i - 1], b = pv;
                    while (ms.size() >= 2) {
                        long m1 = ms.get(ms.size() - 2), b1 = bs.get(bs.size() - 2);
                        long m2 = ms.get(ms.size() - 1), b2 = bs.get(bs.size() - 1);
                        if ((b - b1) * (m1 - m2) <= (b2 - b1) * (m1 - m)) { ms.remove(ms.size() - 1); bs.remove(bs.size() - 1); }
                        else break;
                    }
                    ms.add(m); bs.add(b);
                }
                if (!ms.isEmpty()) {
                    long x = pre[i] + (long) k * j;
                    if (ptr >= ms.size()) ptr = ms.size() - 1;
                    while (ptr + 1 < ms.size() && ms.get(ptr + 1) * x + bs.get(ptr + 1) <= ms.get(ptr) * x + bs.get(ptr)) ptr++;
                    nd[i] = ms.get(ptr) * x + bs.get(ptr) + x * cs[i];
                }
            }
            long[] tmp = dp; dp = nd; nd = tmp;
        }
        return dp[n];
    }
}

